import React from 'react';

export default function PuppiesView({ puppies, activeFilters, updateFilter, showPuppyDetail }) {
  const filteredPuppies = puppies.filter(puppy => {
    const matchWhere = activeFilters.where === 'Everywhere' || puppy.where === activeFilters.where;
    const matchBreed = activeFilters.breeds.length === 0 || activeFilters.breeds.includes(puppy.breed);
    const matchGender = activeFilters.genders.length === 0 || activeFilters.genders.includes(puppy.gender);
    return matchWhere && matchBreed && matchGender;
  });

  const isBtnActive = (type, val) => {
    if (type === 'where') return activeFilters.where === val;
    if (type === 'breed') return activeFilters.breeds.includes(val);
    if (type === 'gender') return activeFilters.genders.includes(val);
    return false;
  };

  const getBtnClass = (type, val) => {
    const active = isBtnActive(type, val);
    const base = "px-4 py-1.5 rounded-full border-2 font-medium transition-colors ";
    return active 
      ? base + "bg-[#4a3b32] text-[#fff9f0] border-[#4a3b32]" 
      : base + "border-[#4a3b32]/30 text-[#4a3b32] hover:border-[#4a3b32]";
  };

  return (
    <main className="animate-fade-in max-w-7xl mx-auto px-6 py-12">
      <h2 className="font-serif text-5xl md:text-6xl font-bold mb-4 text-[#4a3b32]">Available puppies</h2>
      <p className="text-lg mb-8 max-w-2xl text-[#4a3b32]/80">
        Every listing shows real photos of the actual puppy. Open a profile to see them all, then ask us about them on WhatsApp.
      </p>

      {/* Filters */}
      <div className="border-2 border-[#4a3b32] rounded-3xl p-6 bg-white mb-12 shadow-sm space-y-4 text-[#4a3b32]">
        <div className="flex flex-col md:flex-row gap-2 md:items-center">
          <span className="font-semibold w-24 text-[#8c4a2f] italic font-serif">where</span>
          <div className="flex flex-wrap gap-2">
            {['Everywhere', 'Imported', 'Korean Teacup', 'Dubai'].map(loc => (
              <button key={loc} onClick={() => updateFilter('where', loc)} className={getBtnClass('where', loc)}>{loc}</button>
            ))}
          </div>
        </div>
        <div className="flex flex-col md:flex-row gap-2 md:items-center">
          <span className="font-semibold w-24 text-[#8c4a2f] italic font-serif">breed</span>
          <div className="flex flex-wrap gap-2">
            {['Maltipoo', 'Pomeranian', 'Poodle', 'Cavapoo', 'Shih Tzu'].map(breed => (
              <button key={breed} onClick={() => updateFilter('breed', breed)} className={getBtnClass('breed', breed)}>{breed}</button>
            ))}
          </div>
        </div>
        <div className="flex flex-col md:flex-row gap-2 md:items-center">
          <span className="font-semibold w-24 text-[#8c4a2f] italic font-serif">boy or girl</span>
          <div className="flex flex-wrap gap-2">
            {['Boy', 'Girl'].map(gender => (
              <button key={gender} onClick={() => updateFilter('gender', gender)} className={getBtnClass('gender', gender)}>{gender}s</button>
            ))}
          </div>
        </div>
      </div>

      <p className="font-serif italic text-lg mb-6 text-[#4a3b32]/70"><span>{filteredPuppies.length}</span> puppies looking for a home</p>

      {filteredPuppies.length === 0 ? (
        <div className="text-center py-12 text-xl font-serif text-[#4a3b32]/60">No puppies match your exact filters. Try clearing some!</div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-x-8 gap-y-12">
          {filteredPuppies.map(puppy => (
            <div key={puppy.id} onClick={() => showPuppyDetail(puppy.id)} className="cursor-pointer group text-center flex flex-col items-center">
              <div className="relative mb-5 w-full aspect-[4/5] transition-transform duration-300 group-hover:-translate-y-2">
                <div className="absolute inset-0 rounded-[2.5rem] border-2 border-[#4a3b32] shadow-sm" style={{ backgroundColor: puppy.colorBg }}></div>
                <div className="absolute top-4 right-4 bg-white border-2 border-[#4a3b32] px-3 py-1 rounded-full text-xs font-bold z-10 flex items-center gap-1 shadow-sm text-[#4a3b32]">🐾 Available</div>
                <div className="absolute inset-2 bg-white overflow-hidden border-2 border-[#4a3b32]/10" style={{ borderRadius: '50% 50% 20px 20px / 60% 60% 20px 20px' }}>
                  <img src={puppy.image} alt={puppy.breed} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                </div>
              </div>
              <h3 className="font-serif text-3xl font-bold mb-1 text-[#4a3b32] group-hover:text-[#8c4a2f] transition-colors">{puppy.name}</h3>
              <p className="text-sm font-medium text-[#4a3b32]/70 uppercase tracking-wide">{puppy.breed} • {puppy.gender}</p>
              <p className="text-xs text-[#4a3b32]/50 mt-1">{puppy.where} • {puppy.age}</p>
            </div>
          ))}
        </div>
      )}
    </main>
  );
}
